<script setup lang="ts">
const db=useDb(),w=useWorkspace(),form=ref<any>({...w.value}),{error,busy,notice,run}=useAction(),owner=ref(false)
const {data}=await db.auth.getUser();owner.value=!!check(await db.from('quolyn_workspace_members').select('role').eq('workspace_id',w.value!.id).eq('user_id',data.user!.id).single())?.role.match(/^owner$/)
const {data:analysisStatus,error:statusError}=await useAsyncData('analysis-status',async()=>{const r=await db.functions.invoke('analyse-enquiry',{body:{action:'status',workspace_id:w.value!.id}});if(r.error)throw r.error;return r.data as {aiConfigured:boolean}})
const unitForm=reactive({code:'',label:'',dimension:'area',base_factor:''})
const {data:customUnits,refresh:refreshUnits}=await useAsyncData('workspace-units',async()=>check(await db.from('quolyn_units').select('*').eq('workspace_id',w.value!.id).order('code')))
async function saveUnit(){await run(async()=>{check(await db.from('quolyn_units').upsert({...unitForm,workspace_id:w.value!.id},{onConflict:'workspace_id,code'}));await refreshUnits();await refreshNuxtData('unit-options-'+w.value!.id);notice.value='Unit conversion saved. Existing issued snapshots are preserved.'})}
async function save(){await run(async()=>{const {id,created_at,...p}=form.value;check(await db.from('quolyn_workspaces').update(p).eq('id',w.value!.id));w.value={...form.value};notice.value='Workspace settings saved'})}
async function logo(e:Event){await run(async()=>{const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>2097152)throw new Error('Use PNG or JPEG under 2 MB');const path=`${w.value!.id}/${crypto.randomUUID()}.${file.type==='image/png'?'png':'jpg'}`;check(await db.storage.from('workspace-assets').upload(path,file));form.value.logo_path=path;notice.value='Logo uploaded. Save settings to use it.'})}
async function demo(){await run(async()=>{if(!window.confirm('Add fictional Northfield demo products and Oakline customer to this workspace? Existing records are preserved.'))return;await $fetch('/api/demo',{method:'POST'});notice.value='Fictional demo catalogue, customer and two enquiries added. Open Enquiries to begin.'})}
</script>
<template><div><div class="page-title"><div><div class="eyebrow">WORKSPACE PREFERENCES</div><h1>Settings</h1><p>Business identity, commercial defaults and pilot tools.</p></div></div><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success">{{notice}}</p><form class="panel" @submit.prevent="save"><h2>Distributor identity</h2><fieldset :disabled="!owner||busy" style="border:0;padding:0"><div class="form-grid"><label>Business name<input v-model="form.name" required></label><label>Logo (PNG / JPEG)<input type="file" accept="image/png,image/jpeg" @change="logo"></label></div><label>Business address<textarea v-model="form.address"></textarea></label><div class="form-grid"><label>Default currency<select v-model="form.currency"><option v-for="c in ['INR','USD','EUR','GBP','AED','JPY','KWD']" :key="c">{{c}}</option></select></label><label>Default tax basis points<input v-model.number="form.tax_bps" type="number" min="0" max="10000" placeholder="Unknown"></label><label>Quote prefix<input v-model="form.quote_prefix" required maxlength="20"></label><label>Validity (days)<input v-model.number="form.validity_days" type="number" min="1" max="365"></label><label>Discount warning threshold (bps)<input v-model.number="form.discount_warning_bps" type="number" min="0" max="10000"></label><label>Margin warning threshold (bps)<input v-model.number="form.margin_warning_bps" type="number" min="0" max="10000"></label></div><label>Terms and conditions<textarea v-model="form.terms"></textarea></label><button class="primary" :disabled="busy">Save settings</button></fieldset><p v-if="!owner" class="muted">Only the workspace owner can change these settings.</p></form><div class="panel"><h2>Additional compatible units</h2><p class="muted">Configure an explicit factor to square metres, linear metres or each. Conversions across different dimensions are blocked. Boxes use each product’s pack coverage.</p><div v-for="u in customUnits" :key="u.id" class="row between"><span>{{u.label}} ({{u.code}}) · {{u.base_factor}} {{u.dimension==='area'?'m²':u.dimension==='length'?'linear metres':'each'}}</span><button v-if="owner" class="link" @click="Object.assign(unitForm,{code:u.code,label:u.label,dimension:u.dimension,base_factor:String(u.base_factor)})">Edit factor</button></div><form v-if="owner" @submit.prevent="saveUnit"><div class="form-grid"><label>Unit code<input v-model="unitForm.code" required pattern="[a-z][a-z0-9_]{0,15}" placeholder="e.g. yd2"></label><label>Display name<input v-model="unitForm.label" required placeholder="Square yard"></label><label>Dimension<select v-model="unitForm.dimension"><option value="area">Area (base: m²)</option><option value="length">Length (base: linear metre)</option><option value="count">Count (base: each)</option></select></label><label>Base units in one new unit<input v-model="unitForm.base_factor" type="number" min="0.000000001" step="any" required placeholder="0.83612736 for square yard"></label></div><button class="secondary" :disabled="busy">Save unit conversion</button></form></div><div class="panel"><h2>Enquiry analysis</h2><div class="row"><span class="pill confirmed">Deterministic mode available</span><span v-if="analysisStatus" class="pill" :class="analysisStatus.aiConfigured?'confirmed':'warning'">{{analysisStatus.aiConfigured?'AI extraction configured':'AI extraction not configured'}}</span><span v-if="statusError" class="pill warning">Provider status unavailable</span></div><p class="muted">Optional AI requires server-side provider configuration. Credentials are never entered in this workspace. Analysis failures remain visible, and manual review is always available.</p></div><div class="panel"><h2>Explore with fictional data</h2><p class="muted">Add 30 Northfield Surfaces products, Oakline Interiors, and two example enquiries. All names, specifications and prices are fictional.</p><button class="secondary" :disabled="busy" @click="demo">Load fictional demo data</button></div></div></template>
